// and updates the slice with the returned rows.
func (o AuthSessionSlice) MergeMod() bob.Mod[*dialect.MergeQuery] {
	return bob.ModFunc[*dialect.MergeQuery](func(q *dialect.MergeQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return AuthSessions.BeforeMergeHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *AuthSession:
				o.copyMatchingRows(retrieved)
			case []*AuthSession:
				o.copyMatchingRows(retrieved...)
			case AuthSessionSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a AuthSession or a slice of AuthSession
				// then run the AfterMergeHooks on the slice
				_, err = AuthSessions.AfterMergeHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))
	})
}

func (o AuthSessionSlice) UpdateAll(ctx context.Context, exec bob.Executor, vals AuthSessionSetter) error {
	if len(o) == 0 {
		return nil
	}

	_, err := AuthSessions.Update(vals.UpdateMod(), o.UpdateMod()).All(ctx, exec)
	return err
}

func (o AuthSessionSlice) DeleteAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	_, err := AuthSessions.Delete(o.DeleteMod()).Exec(ctx, exec)
	return err
}

func (o AuthSessionSlice) ReloadAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	o2, err := AuthSessions.Query(sm.Where(o.pkIN())).All(ctx, exec)
	if err != nil {
		return err
	}

	o.copyMatchingRows(o2...)

	return nil
}

type authSessionWhere[Q psql.Filterable] struct {
	cols           authSessionColumns
	ID             psql.WhereMod[Q, int32]
	SessionIDHash  psql.WhereMod[Q, []byte]
	Principal      psql.WhereMod[Q, types.JSON[json.RawMessage]]
	AccessToken    psql.WhereMod[Q, string]
	RefreshToken   psql.WhereMod[Q, string]
	TokenExpiresAt psql.WhereNullMod[Q, time.Time]
	ExpiresAt      psql.WhereNullMod[Q, time.Time]
	CreatedAt      psql.WhereMod[Q, time.Time]
	UpdatedAt      psql.WhereMod[Q, time.Time]
	CreatedBy      psql.WhereMod[Q, string]
	UpdatedBy      psql.WhereMod[Q, string]
}

func (authSessionWhere[Q]) AliasedAs(alias string) authSessionWhere[Q] {
	return buildAuthSessionWhere[Q](buildAuthSessionColumns(alias))
}

func buildAuthSessionWhere[Q psql.Filterable](cols authSessionColumns) authSessionWhere[Q] {
	return authSessionWhere[Q]{
		cols:           cols,
		ID:             psql.Where[Q, int32](cols.ID.Expression),
		SessionIDHash:  psql.Where[Q, []byte](cols.SessionIDHash.Expression),
		Principal:      psql.Where[Q, types.JSON[json.RawMessage]](cols.Principal.Expression),
		AccessToken:    psql.Where[Q, string](cols.AccessToken.Expression),
		RefreshToken:   psql.Where[Q, string](cols.RefreshToken.Expression),
		TokenExpiresAt: psql.WhereNull[Q, time.Time](cols.TokenExpiresAt.Expression),
		ExpiresAt:      psql.WhereNull[Q, time.Time](cols.ExpiresAt.Expression),
		CreatedAt:      psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:      psql.Where[Q, time.Time](cols.UpdatedAt.Expression),
		CreatedBy:      psql.Where[Q, string](cols.CreatedBy.Expression),
		UpdatedBy:      psql.Where[Q, string](cols.UpdatedBy.Expression),
	}
}
